#include "Core.hpp"
#include <iostream>
#include "MonitorTests.hpp"
int main(int argc,char** argv){using namespace udm;try{if(argc==3&&(std::string(argv[1])=="--broker-test"||std::string(argv[1])=="--broker-protocol-test")){auto report=monitorTests(std::string(argv[1])=="--broker-test");std::ofstream output(fs::path(wide(argv[2])));output<<report.dump(2);output.close();if(!output)throw std::runtime_error("Cannot save broker test report.");std::cout<<report.dump(2)<<std::endl;return report["Failed"]==0?0:1;}
if(argc==3&&std::string(argv[1])=="--broker-orphan-fixture"){Monitor fixture;fixture.watch({GetCurrentProcessId()});std::ofstream out(fs::path(wide(argv[2])));out<<fixture.snapshot().dump();out.close();if(!out)throw std::runtime_error("Cannot save orphan fixture handshake.");Sleep(60000);return 0;}
if(argc>1&&std::string(argv[1])=="--diagnose"){std::cout<<diagnostics().dump()<<std::endl;return 0;}if(argc>1&&std::string(argv[1])=="--endpoints"){std::cout<<endpoints().dump()<<std::endl;return 0;}if(argc<2||std::string(argv[1])=="--status"){auto status=diagnostics();std::cout<<status.dump()<<std::endl;return status.value("RuntimeVerified",false)?0:1;}Monitor monitor;bool captureMode=argc>1&&std::string(argv[1])=="--capture";if(argc<3||(!captureMode&&std::string(argv[1])!="--watch")||(captureMode&&argc<4))throw std::runtime_error("Usage: --diagnose | --status | --endpoints | --watch PID[,PID...] [seconds] | --capture PID[,PID...] PORT[,PORT...] [seconds]");std::vector<unsigned> ports;if(captureMode){for(auto word:words(argv[3])){size_t used=0;auto value=std::stoul(word,&used);if(used!=word.size()||value<1||value>65535)throw std::runtime_error("Invalid TCP port.");ports.push_back(static_cast<unsigned>(value));}ports=udmbroker::capturePorts(Json(ports));if(ports.empty())throw std::runtime_error("Choose at least one TCP port.");}int durationIndex=captureMode?4:3;int seconds=argc>durationIndex?std::stoi(argv[durationIndex]):10;if(seconds<1||seconds>3600)throw std::runtime_error("Use 1-3600 seconds.");std::map<DWORD,FILETIME> identities;for(auto word:words(argv[2])){DWORD id=(DWORD)std::stoul(word);Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,id));FILETIME created{},exit{},kernel{},user{};if(!p||WaitForSingleObject(p.h,0)!=WAIT_TIMEOUT||!GetProcessTimes(p.h,&created,&exit,&kernel,&user))throw std::runtime_error("Cannot identify selected process.");identities[id]=created;}for(int i=0;i<seconds;++i){std::vector<DWORD> pids;for(auto it=identities.begin();it!=identities.end();){Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,it->first));FILETIME created{},exit{},kernel{},user{};if(!p||WaitForSingleObject(p.h,0)!=WAIT_TIMEOUT||!GetProcessTimes(p.h,&created,&exit,&kernel,&user)||CompareFileTime(&created,&it->second)!=0)it=identities.erase(it);else{pids.push_back(it->first);++it;}}monitor.watch(pids);if(captureMode&&!pids.empty())monitor.capture(ports);std::cout<<monitor.snapshot().dump()<<std::endl;Sleep(1000);}monitor.watch({});return 0;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
